const state={markets:[],produce:[],chatbot:[],bookmarks:JSON.parse(sessionStorage.getItem('ff_bookmarks')||'[]'),notes:JSON.parse(sessionStorage.getItem('ff_notes')||'{}'),query:'',selectedNote:null};
const app=document.getElementById('app');
const VISIT_KEY='ff_total_visits_v2';
function updateVisitCounter(){
  const current=Number(localStorage.getItem(VISIT_KEY)||0)+1;
  localStorage.setItem(VISIT_KEY,String(current));
  ['headerVisitors','visitorCount','aboutVisitors'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=current.toLocaleString();});
}
function updateDateTime(){
  const now=new Date();
  const dateText=now.toLocaleDateString('en-PK',{day:'2-digit',month:'long',year:'numeric'});
  const timeText=now.toLocaleTimeString('en-PK',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true});
  const d=document.getElementById('liveDate'), h=document.getElementById('headerClock'), home=document.getElementById('liveClock'), about=document.getElementById('aboutClock');
  if(d)d.textContent=dateText;if(h)h.textContent=timeText;if(home)home.textContent=timeText;if(about)about.textContent=timeText;
}
function startGlobalClock(){updateDateTime();clearInterval(window.__globalClock);window.__globalClock=setInterval(updateDateTime,1000);}
function searchFromNavbar(){
  const q=document.getElementById('navSearch')?.value.trim()||'';
  location.hash='#directory';
  setTimeout(()=>{const i=document.getElementById('dirSearch');if(i){i.value=q;applyDirectory();i.focus();}},0);
}
function setupHeaderSearch(){
  const input=document.getElementById('navSearch'), btn=document.getElementById('navSearchBtn'), focus=document.getElementById('focusSearch');
  if(btn)btn.onclick=searchFromNavbar;
  if(input)input.addEventListener('keydown',e=>{if(e.key==='Enter')searchFromNavbar();});
  if(focus)focus.onclick=()=>input?.focus();
  updateVisitCounter();startGlobalClock();
}

