async function loadData(){try{const [m,p,c]=await Promise.all([fetch('data/markets.json'),fetch('data/produce.json'),fetch('data/chatbot.json')]);if(!m.ok||!p.ok||!c.ok)throw Error();state.markets=await m.json();state.produce=await p.json();state.chatbot=await c.json()}catch(e){state.markets=fallbackMarkets;state.produce=fallbackProduce;state.chatbot=[];toast('Live JSON unavailable — demo fallback loaded. Use VS Code Live Server for full JSON mode.')}route();}
function route(){const raw=location.hash.slice(1)||'home';const [page,id]=raw.split('/');({home:renderHome,directory:renderDirectory,market:()=>renderMarket(id),produce:()=>id?renderProduceDetail(id):renderProduce,bookmarks:renderBookmarks,about:renderAbout,seasonal:renderSeasonal,contact:renderContact}[page]||renderHome)();document.querySelectorAll('#mainNav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${page}`));window.scrollTo({top:0,behavior:'smooth'});}
window.addEventListener('hashchange',route);
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function isSaved(type,id){return state.bookmarks.some(x=>x.type===type&&x.id===id)}
function saveState(){sessionStorage.setItem('ff_bookmarks',JSON.stringify(state.bookmarks));sessionStorage.setItem('ff_notes',JSON.stringify(state.notes));}
function toggleBookmark(type,id){const i=state.bookmarks.findIndex(x=>x.type===type&&x.id===id);if(i>=0){state.bookmarks.splice(i,1);toast('Removed from bookmarks')}else{state.bookmarks.push({type,id,added:new Date().toISOString()});toast('Saved to bookmarks')}saveState();route();}
