function marketCard(m){const marketImg=REAL_MARKET_IMAGES[m.id]||REAL_MARKET_IMAGE;return `<article class="market-card"><div class="card-image"><img src="${marketImg}" alt="Representative real market photo for ${esc(m.area)}" loading="lazy" onerror="this.onerror=null;this.src=REAL_MARKET_IMAGE"><span class="pill">${esc(m.area)}</span><button class="heart ${isSaved('market',m.id)?'saved':''}" onclick="toggleBookmark('market','${m.id}')" aria-label="Bookmark ${esc(m.name)}">${isSaved('market',m.id)?'★':'☆'}</button></div><div class="card-body"><h3>${esc(m.name)}</h3><div class="meta"><span class="ui-icon">●</span> ${esc(m.address)}<br><span class="ui-icon">▣</span> ${esc(m.days.join(' • '))}<br><span class="ui-icon">◷</span> ${esc(m.hours)}<br><span class="${marketIsOpen(m)?'open-now':'closed-now'}">${marketIsOpen(m)?'● Open now':'○ Currently closed'}</span></div><div class="chips">${m.produce.slice(0,4).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="card-actions"><a class="small-btn primaryish" href="#market/${m.id}">View details →</a><button class="small-btn" onclick="openNote('market','${m.id}')">Add note</button></div></div></article>`}
function produceCard(p){const realImg=REAL_PRODUCE_IMAGES[p.name]||p.image;return `<article class="produce-card"><div class="card-image"><img src="${realImg}" alt="Real photo of ${esc(p.name)}" loading="lazy" onerror="this.onerror=null;this.src=REAL_MARKET_IMAGE"><span class="pill">${esc(p.category)}</span><button class="heart ${isSaved('produce',p.id)?'saved':''}" onclick="toggleBookmark('produce','${p.id}')" aria-label="Bookmark ${esc(p.name)}">${isSaved('produce',p.id)?'★':'☆'}</button></div><div class="card-body"><h3>${esc(p.name)}</h3><div class="meta"><strong>Season:</strong> ${esc(p.season)}<br>${esc(p.description)}</div><div class="chips">${p.markets.slice(0,2).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="card-actions"><a class="small-btn primaryish" href="#produce/${p.id}">View details →</a><button class="small-btn" onclick="shareText('${esc(p.name)}','${esc(p.description)}')">Share</button></div></div></article>`}
function renderHome(){const featured=state.markets.slice(0,3), picks=state.produce.slice(0,4);const visitors=Number(localStorage.getItem(VISIT_KEY)||1);app.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">Fresh All Along</span><h1>Nature’s Freshness <em>Right to Your Home</em></h1><p>Discover nearby farmers markets, check their schedules, and explore seasonal fruits, vegetables and herbs — all in one simple place.</p><div class="search-box"><input id="homeSearch" placeholder="Search markets, areas, vegetables..." aria-label="Find a market"><button class="primary" onclick="goSearch()">Find a Market →</button></div><div class="hero-stats"><div class="stat"><strong><span class="ui-icon">✦</span> ${state.markets.length || 6}</strong><span>Market Listings</span></div><div class="stat"><strong><span class="ui-icon">◆</span> ${state.produce.length || 10}</strong><span>Produce Guides</span></div><div class="stat"><strong><span class="ui-icon">◷</span> <span id="liveClock">--:--:--</span></strong><span>Live Local Time</span></div><div class="stat"><strong><span class="ui-icon">●</span> <span id="visitorCount">${visitors}</span></strong><span>Visits Recorded</span></div></div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Featured showcase</span><h2 id="featuredTitle">${esc(featured[0]?.name||'Featured Market')}</h2><p id="featuredText">${esc(featured[0]?.description||'Discover a nearby farmers market.')}</p></div></div><div class="featured-strip" id="featuredStrip"></div></section><section class="section location-section"><div class="location-card"><div><span class="eyebrow">Right now</span><h2>Nearby Market Status</h2><p id="nearbyStatus" class="meta">Allow browser location to highlight the nearest market and show which nearby markets are open right now.</p></div><button class="primary" onclick="requestUserLocation()">Use My Location</button></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Explore local markets</span><h2>Find a Market Near You</h2><p>Search by area, day or produce type and open a detailed market profile.</p></div><a class="text-link" href="#directory">View all →</a></div><div class="cards">${featured.map(marketCard).join('')}</div></section><section class="section alt"><div class="section-head"><div><span class="eyebrow">Seasonal discovery</span><h2>Fresh Picks for a Healthier You</h2><p>Browse popular produce and see which markets usually carry it.</p></div><a class="text-link" href="#produce">Produce Guide →</a></div><div class="category-grid">${['Vegetables','Fruits','Leafy Greens','Herbs','Organic Picks','Seasonal'].map(c=>`<a class="category" href="#produce"><img src="${REAL_CATEGORY_IMAGES[c]}" alt="Real ${c} produce photo" loading="lazy" onerror="this.onerror=null;this.src=REAL_MARKET_IMAGE"><strong>${c}</strong><span class="meta">Explore fresh picks</span></a>`).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">This week</span><h2>Seasonal Produce</h2></div></div><div class="produce-grid">${picks.map(produceCard).join('')}</div></section>`;setTimeout(()=>{const i=document.getElementById('homeSearch');if(i)i.addEventListener('keydown',e=>{if(e.key==='Enter')goSearch()});const strip=document.getElementById('featuredStrip');if(strip){let fi=0;const paint=()=>{const m=state.markets[fi%state.markets.length];strip.innerHTML=marketCard(m);document.getElementById('featuredTitle').textContent=m.name;document.getElementById('featuredText').textContent=m.description;fi++;};paint();clearInterval(window.__featured);window.__featured=setInterval(paint,4500);}startClock();renderNearbyStatus()},0);}
function goSearch(){const q=document.getElementById('homeSearch')?.value.trim()||'';location.hash='#directory';setTimeout(()=>{const i=document.getElementById('dirSearch');if(i){i.value=q;applyDirectory()}},0)}

function startClock(){startGlobalClock()}
function marketIsOpen(m){const now=new Date();const day=now.toLocaleDateString('en-US',{weekday:'long'});if(!m.days.includes(day))return false;const match=m.hours.match(/(\d{1,2}):(\d{2})\s*(AM|PM)\s*-\s*(\d{1,2}):(\d{2})\s*(AM|PM)/i);if(!match)return false;const toMin=(h,mi,ap)=>{h=Number(h)%12+(ap.toUpperCase()==='PM'?12:0);return h*60+Number(mi)};const n=now.getHours()*60+now.getMinutes();return n>=toMin(match[1],match[2],match[3])&&n<=toMin(match[4],match[5],match[6])}
function renderDirectory(){app.innerHTML=`<section class="directory-hero"><span class="eyebrow">Market discovery</span><h1>Market Directory</h1><p class="meta">Browse farmer markets loaded from the project's static JSON dataset.</p><div class="toolbar"><input class="control" id="dirSearch" placeholder="Search market, area or produce..."><select class="control" id="areaFilter"><option value="">All areas</option>${[...new Set(state.markets.map(m=>m.area))].sort().map(a=>`<option>${esc(a)}</option>`).join('')}</select><select class="control" id="dayFilter"><option value="">Any day</option>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<option>${d}</option>`).join('')}</select><select class="control" id="produceFilter"><option value="">Any produce</option>${[...new Set(state.produce.map(p=>p.name))].sort().map(p=>`<option>${esc(p)}</option>`).join('')}</select></div></section><section class="section"><div class="section-head"><div><span class="results-count" id="resultsCount"></span></div><select class="control" id="sortFilter"><option value="name">Sort alphabetically</option><option value="proximity">Sort by proximity</option><option value="next">Sort by next open day</option></select></div><div class="cards" id="marketResults"></div></section>`;['dirSearch','areaFilter','dayFilter','produceFilter','sortFilter'].forEach(id=>document.getElementById(id).addEventListener('input',applyDirectory));applyDirectory();}
function applyDirectory(){let list=[...state.markets];const q=(document.getElementById('dirSearch')?.value||'').toLowerCase(),area=document.getElementById('areaFilter')?.value||'',day=document.getElementById('dayFilter')?.value||'',prod=document.getElementById('produceFilter')?.value||'',sort=document.getElementById('sortFilter')?.value||'name';if(q)list=list.filter(m=>(m.name+' '+m.area+' '+m.produce.join(' ')).toLowerCase().includes(q));if(area)list=list.filter(m=>m.area===area);if(day)list=list.filter(m=>m.days.includes(day));if(prod)list=list.filter(m=>m.produce.includes(prod));list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='proximity'&&window.__userLocation?distanceSq(a)-distanceSq(b):a.nextOpen.localeCompare(b.nextOpen));document.getElementById('resultsCount').textContent=`${list.length} market${list.length===1?'':'s'} found`;document.getElementById('marketResults').innerHTML=list.length?list.map(marketCard).join(''):`<div class="empty">No markets match these filters. Try another area, day or produce item.</div>`;}
function renderMarket(id){const m=state.markets.find(x=>x.id===id);if(!m){renderDirectory();return}const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];const dayRows=days.map(d=>{const open=m.days.includes(d);return `<tr><td>${d}</td><td>${open?'Open':'Closed'}</td><td>${open?esc(m.hours):'—'}</td></tr>`}).join('');const products=m.produce.map(name=>{const p=state.produce.find(x=>x.name===name);return p?`<a class="mini-produce" href="#produce"><img src="${REAL_PRODUCE_IMAGES[p.name]||p.image}" alt="${esc(p.name)}"><span>${esc(p.name)}</span></a>`:`<span class="chip">${esc(name)}</span>`}).join('');app.innerHTML=`<div class="breadcrumb"><a href="#home">Home</a> / <a href="#directory">Market Directory</a> / ${esc(m.name)}</div><section class="detail"><div class="detail-card"><img class="detail-photo" src="${REAL_MARKET_IMAGES[m.id]||REAL_MARKET_IMAGE}" alt="Representative real market photo for ${esc(m.area)}" loading="lazy" onerror="this.onerror=null;this.src=REAL_MARKET_IMAGE"><span class="eyebrow" style="margin-top:20px">Market detail</span><h1 style="font-family:'Playfair Display',serif;font-size:42px;margin:0 0 10px">${esc(m.name)}</h1><p class="meta">${esc(m.description)}</p><div class="notice"><span class="ui-icon">◷</span> <strong>Current status:</strong> ${marketIsOpen(m)?'Open now':'Currently closed'}</div><h3>Weekly Schedule</h3><div class="table-wrap"><table class="schedule-table"><thead><tr><th>Day</th><th>Status</th><th>Hours</th></tr></thead><tbody>${dayRows}</tbody></table></div><h3>Typical Produce</h3><div class="produce-mini-grid">${products}</div><div class="card-actions"><button class="primary" onclick="toggleBookmark('market','${m.id}')">${isSaved('market',m.id)?'★ Saved':'☆ Bookmark Market'}</button><button class="small-btn" onclick="openNote('market','${m.id}')">Add session note</button><button class="small-btn" onclick="shareText('${esc(m.name)}','${esc(m.description)}')">Share</button></div></div><aside class="detail-card"><h3>Location</h3><p class="meta"><span class="ui-icon">●</span> ${esc(m.address)}</p><iframe class="map" loading="lazy" src="https://www.google.com/maps?q=${m.lat||24.86},${m.lng||67.01}&output=embed" title="Map for ${esc(m.name)}"></iframe><p class="meta" style="margin-top:12px">Use the map to plan your visit. Browser geolocation is optional and only used after permission.</p></aside></section>`}
function renderSeasonal(){const seasonal=state.produce.filter(p=>String(p.season||'').toLowerCase()!=='year-round');const picks=seasonal.length?seasonal:state.produce;app.innerHTML=`<section class="page-banner"><span class="eyebrow">Seasonal discovery</span><h1>Seasonal Recommendations</h1><p class="meta">Explore this week’s recommended fresh produce and discover markets where you can usually find it.</p></section><section class="section"><div class="section-head"><div><span class="eyebrow">Fresh this week</span><h2>Recommended Seasonal Produce</h2><p>Plan your market visit around fresh, seasonal choices.</p></div><a class="text-link" href="#directory">Find a Market →</a></div><div class="produce-grid">${picks.map(produceCard).join('')}</div></section>`;}

function renderProduce(){const categories=['Fruits','Vegetables','Herbs','Dairy','Leafy Greens','Root Vegetables','Organic','Grains','Other'];app.innerHTML=`<section class="page-banner"><span class="eyebrow">Fresh produce library</span><h1>Produce Guide</h1><p class="meta">Browse fruits, vegetables, herbs, dairy and other produce types, then check their seasons and related markets.</p><div class="toolbar"><input class="control" id="produceSearch" placeholder="Search produce..."><select class="control" id="produceCat"><option value="">All Categories</option>${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select class="control" id="produceSeason"><option value="">All Seasons</option>${[...new Set(state.produce.map(p=>p.season))].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div><div class="category-chips">${categories.map(c=>`<button class="category-filter" type="button" onclick="setProduceCategory('${esc(c)}')">${esc(c)}</button>`).join('')}</div></section><section class="section"><div class="produce-grid" id="produceResults"></div></section>`;['produceSearch','produceCat','produceSeason'].forEach(id=>document.getElementById(id).addEventListener('input',applyProduce));applyProduce();}
function setProduceCategory(category){const select=document.getElementById('produceCat');if(select){select.value=category;}applyProduce()}
function renderProduceDetail(id){const p=state.produce.find(x=>x.id===id);if(!p){renderProduce();return}const realImg=REAL_PRODUCE_IMAGES[p.name]||p.image;const marketLinks=p.markets.map(name=>{const m=state.markets.find(x=>x.name===name);return m?`<a class="chip" href="#market/${m.id}">${esc(name)} →</a>`:`<span class="chip">${esc(name)}</span>`}).join('');app.innerHTML=`<div class="breadcrumb"><a href="#home">Home</a> / <a href="#produce">Produce Guide</a> / ${esc(p.name)}</div><section class="detail"><div class="detail-card"><img class="detail-photo" src="${realImg}" alt="Real photo of ${esc(p.name)}" loading="lazy" onerror="this.onerror=null;this.src=REAL_MARKET_IMAGE"><span class="eyebrow" style="margin-top:20px">Produce detail</span><h1 style="font-family:'Playfair Display',serif;font-size:42px;margin:0 0 10px">${esc(p.name)}</h1><p class="meta">${esc(p.description)}</p><div class="notice">🌿 <strong>Category:</strong> ${esc(p.category)} &nbsp; • &nbsp; <strong>Season:</strong> ${esc(p.season)}</div><h3>Markets where you can usually find it</h3><div class="chips">${marketLinks}</div><div class="card-actions"><button class="primary" onclick="toggleBookmark('produce','${p.id}')">${isSaved('produce',p.id)?'♥ Saved':'♡ Bookmark Produce'}</button><button class="small-btn" onclick="shareText('${esc(p.name)}','${esc(p.description)}')">Share</button><a class="small-btn" href="#produce">Back to Produce Guide</a></div></div><aside class="detail-card"><h3>FreshFind Guide</h3><p class="meta">Use this page to check the produce category, season and markets where the item is usually available.</p><img class="detail-photo" src="${realImg}" alt="${esc(p.name)}" loading="lazy"></aside></section>`;}

function applyProduce(){const q=(document.getElementById('produceSearch')?.value||'').toLowerCase(),c=document.getElementById('produceCat')?.value||'',s=document.getElementById('produceSeason')?.value||'';let list=state.produce.filter(p=>(!q||(p.name+' '+p.description+' '+p.category).toLowerCase().includes(q))&&(!c||p.category===c)&&(!s||p.season===s));document.getElementById('produceResults').innerHTML=list.length?list.map(produceCard).join(''):`<div class="empty">No produce found for this filter.</div>`}
function renderBookmarks(){const items=state.bookmarks.map(b=>{const d=b.type==='market'?state.markets.find(x=>x.id===b.id):state.produce.find(x=>x.id===b.id);return d?{...b,d}:null}).filter(Boolean);app.innerHTML=`<section class="page-banner"><span class="eyebrow">Your saved picks</span><h1>Bookmarks</h1><p class="meta">Favorites and notes are stored in this browser session only. Nothing is sent to a server.</p><div class="card-actions"><button class="primary" onclick="exportBookmarks()">Export Bookmarks</button><button class="small-btn" onclick="shareText('My FreshFind picks','I saved fresh market and produce recommendations in FreshFind.')">Share Recommendations</button></div></section><section class="section">${items.length?`<div class="bookmarks-grid">${items.map(x=>`<div class="bookmark-row"><img src="${x.type==='produce'?(REAL_PRODUCE_IMAGES[x.d.name]||x.d.image):REAL_MARKET_IMAGE}" alt="${esc(x.d.name)}"><div style="flex:1"><strong>${esc(x.d.name)}</strong><div class="meta">${x.type==='market'?esc(x.d.area):esc(x.d.category)}</div><div class="meta">${state.notes[`${x.type}:${x.id}`]?`<span class="ui-icon">▤</span> ${esc(state.notes[`${x.type}:${x.id}`])}`:'No note added yet.'}</div></div><button class="small-btn" onclick="openNote('${x.type}','${x.id}')">Note</button><button class="heart saved" onclick="toggleBookmark('${x.type}','${x.id}')">★</button></div>`).join('')}</div>`:`<div class="empty"><h3>No bookmarks yet</h3><p>Use the heart button on a market or produce card to save it here.</p><a class="primary" href="#directory">Explore markets</a></div>`}</section>`}
function renderAbout(){const visitors=Number(localStorage.getItem(VISIT_KEY)||0);app.innerHTML=`<section class="page-banner"><span class="eyebrow">About the platform</span><h1>FreshFind</h1><p class="meta">A responsive single-page portal designed to help residents discover nearby farmers markets, understand schedules and explore seasonal produce.</p><div class="about-stats"><div class="about-stat"><strong><span class="ui-icon">●</span> <span id="aboutVisitors">${visitors.toLocaleString()}</span></strong><span>Visits Recorded</span></div><div class="about-stat"><strong><span class="ui-icon">◷</span> <span id="aboutClock">--:--:--</span></strong><span>Real-Time Local Clock</span></div></div></section><section class="section"><div class="feature-grid"><div class="feature-card"><div class="feature-icon">●</div><h3>Market Discovery</h3><p>Find farmers markets by area, day and produce type, with market details, operating hours and location information.</p></div><div class="feature-card"><div class="feature-icon">◆</div><h3>Seasonal Produce</h3><p>Browse produce by category and season, and see the markets where each listed item can usually be found.</p></div><div class="feature-card"><div class="feature-icon">✦</div><h3>FreshFind Guide</h3><p>Use the floating rule-based chatbot for common questions about markets, produce and operating hours.</p></div><div class="feature-card"><div class="feature-icon">▣</div><h3>Responsive Experience</h3><p>FreshFind is designed for desktop, tablet and mobile browsers with accessible navigation and clear interface elements.</p></div></div></section>`;updateVisitCounter();updateDateTime();}
function renderContact(){app.innerHTML=`<section class="page-banner"><span class="eyebrow">Get in touch</span><h1>Contact Us</h1><p class="meta">Static contact information and a map are provided for the project demo.</p></section><section class="section"><div class="contact-grid"><div class="contact-card"><h2>FreshFind Team</h2><div class="contact-item"><strong>📧 Email</strong><br><span class="meta">muhammadahmer881@gmail.com</span></div><div class="contact-item"><strong>☎ Phone</strong><br><span class="meta">03122514038</span></div><div class="contact-item"><strong><span class="ui-icon">●</span> Location</strong><br><span class="meta">Shahrah-e-Faisal, Karachi</span></div><button class="primary" style="margin-top:18px" onclick="useLocation()">Use My Location</button><p class="meta" id="geoResult" style="margin-top:12px"></p></div><iframe class="map" id="contactMap" src="https://www.google.com/maps?q=Shahrah-e-Faisal,Karachi&output=embed" loading="lazy" title="FreshFind contact location map"></iframe></div></section>`}
function openNote(type,id){state.selectedNote={type,id};document.getElementById('notesTitle').textContent='Note for '+((type==='market'?state.markets:state.produce).find(x=>x.id===id)?.name||'bookmark');document.getElementById('noteText').value=state.notes[`${type}:${id}`]||'';document.getElementById('notesModal').classList.add('open')}
document.getElementById('saveNote').onclick=()=>{if(!state.selectedNote)return;const key=`${state.selectedNote.type}:${state.selectedNote.id}`;state.notes[key]=document.getElementById('noteText').value.trim();saveState();document.getElementById('notesModal').classList.remove('open');toast('Session note saved');if(location.hash==='#bookmarks')route()};
function exportBookmarks(){const items=state.bookmarks.map(b=>{const d=b.type==='market'?state.markets.find(x=>x.id===b.id):state.produce.find(x=>x.id===b.id);return d?`${b.type.toUpperCase()}: ${d.name}\n${b.type==='market'?d.address:d.season}\nNote: ${state.notes[`${b.type}:${b.id}`]||'—'}\n`:''}).join('\n');const blob=new Blob([`FreshFind Bookmarks\n===================\n\n${items||'No bookmarks saved.'}`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='freshfind-bookmarks.txt';a.click();URL.revokeObjectURL(a.href);toast('Bookmarks exported')}
function shareText(title,text){
  const url=location.href;
  const message=`${title}\n${text}\n${url}`;
  window.__shareData={title,text,url,message};
  const titleEl=document.getElementById('shareTitle'), preview=document.getElementById('sharePreview');
  if(titleEl) titleEl.textContent='Share: '+title;
  if(preview) preview.textContent=message;
  document.getElementById('shareModal')?.classList.add('open');
}
async function copyShareText(){const d=window.__shareData;if(!d)return;try{await navigator.clipboard.writeText(d.message);toast('Share text copied to clipboard')}catch(e){const ta=document.createElement('textarea');ta.value=d.message;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('Share text copied to clipboard')}}
function openShareUrl(base){const d=window.__shareData;if(!d)return;window.open(base+encodeURIComponent(d.message),'_blank','noopener,noreferrer,width=700,height=600')}

function distanceSq(m){const u=window.__userLocation;if(!u)return 0;return ((m.lat||24.86)-u.lat)**2+((m.lng||67.01)-u.lng)**2}
function renderNearbyStatus(){const el=document.getElementById('nearbyStatus');if(!el||!state.markets.length)return;const open=state.markets.filter(m=>marketIsOpen(m));if(!window.__userLocation){el.textContent=open.length?`${open.length} market${open.length===1?' is':'s are'} open right now. Allow location to find the nearest one.`:'No listed market is open right now. Allow location for proximity sorting.';return}const nearest=[...state.markets].sort((a,b)=>distanceSq(a)-distanceSq(b))[0];const nearbyOpen=open.filter(m=>distanceSq(m)<distanceSq(nearest)*4+0.01);el.innerHTML=nearest?`Nearest listed market: <strong>${esc(nearest.name)}</strong>. ${nearbyOpen.length?nearbyOpen.length+' nearby market(s) are open right now.':'No nearby listed market is currently open.'}`:'No market data available.'}
function requestUserLocation(){if(!navigator.geolocation)return; navigator.geolocation.getCurrentPosition(p=>{window.__userLocation={lat:p.coords.latitude,lng:p.coords.longitude}; toast('Location detected — proximity sorting is ready'); renderNearbyStatus(); if(location.hash==='#directory')applyDirectory();},()=>{}, {enableHighAccuracy:false,timeout:5000,maximumAge:300000})}
function useLocation(){const out=document.getElementById('geoResult');if(!navigator.geolocation){out.textContent='Geolocation is not supported by this browser.';return}out.textContent='Requesting browser location…';navigator.geolocation.getCurrentPosition(p=>{window.__userLocation={lat:p.coords.latitude,lng:p.coords.longitude};out.textContent='Live browser location detected. Nearby/open markets can now be highlighted.';const map=document.getElementById('contactMap');if(map)map.src=`https://www.google.com/maps?q=${p.coords.latitude},${p.coords.longitude}&output=embed`;if(location.hash==='#directory')applyDirectory();renderNearbyStatus();},()=>{out.textContent='Location permission was not granted. You can still use area search.'})}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2500)}
function chatbotAnswer(q){const low=q.toLowerCase();const hit=state.chatbot.find(x=>x.keywords.some(k=>low.includes(k)));const answer=hit?.answer||'I can help with market locations, operating hours, produce, seasons and bookmarks. Try asking “Find a market” or “What produce is available?”';if(low.includes('market')||low.includes('find')||low.includes('location'))return answer+' Open <a href="#directory">Market Directory</a>.';if(low.includes('produce')||low.includes('fruit')||low.includes('vegetable'))return answer+' Open <a href="#produce">Produce Guide</a>.';return answer}
function addChat(text,user=false){const box=document.getElementById('chatMessages');const div=document.createElement('div');div.className=user?'user-msg':'bot-msg';if(user)div.textContent=text;else div.innerHTML=text;box.appendChild(div);box.scrollTop=box.scrollHeight}
document.getElementById('chatLauncher').onclick=()=>{document.getElementById('chatPanel').classList.toggle('open');if(document.getElementById('chatPanel').classList.contains('open'))toast('FreshFind chatbot opened');};document.getElementById('closeChat').onclick=()=>document.getElementById('chatPanel').classList.remove('open');document.getElementById('chatForm').onsubmit=e=>{e.preventDefault();const i=document.getElementById('chatInput');const q=i.value.trim();if(!q)return;addChat(q,true);setTimeout(()=>addChat(chatbotAnswer(q)),250);i.value=''};document.querySelectorAll('.quick-replies button').forEach(b=>b.onclick=()=>{const q=b.dataset.q;const answer=chatbotAnswer(q);addChat(q,true);setTimeout(()=>addChat(answer),200);toast('Quick answer: '+q);});
document.getElementById('menuToggle').onclick=()=>document.getElementById('mainNav').classList.toggle('open');document.getElementById('loginBtn').onclick=()=>{document.getElementById('loginModal').classList.add('open');toast('Login popup opened');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).classList.remove('open'));document.getElementById('dummyLogin').onclick=()=>{document.getElementById('loginModal').classList.remove('open');toast('Account login successful');};
document.getElementById('signupBtn').onclick=()=>{document.getElementById('signupModal').classList.add('open');toast('Sign up popup opened');};
document.getElementById('signupForm').onsubmit=e=>{e.preventDefault();const a=document.getElementById('signupPassword').value,b=document.getElementById('signupConfirm').value;if(a!==b){toast('Passwords do not match');return;}document.getElementById('signupForm').reset();document.getElementById('signupModal').classList.remove('open');toast('Account created successfully');};
document.getElementById('shareWhatsApp').onclick=()=>openShareUrl('https://wa.me/?text=');
document.getElementById('shareFacebook').onclick=()=>{const d=window.__shareData;if(d)window.open('https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(d.url),'_blank','noopener,noreferrer,width=700,height=600')};
document.getElementById('shareX').onclick=()=>{const d=window.__shareData;if(d)window.open('https://twitter.com/intent/tweet?text='+encodeURIComponent(d.title+'\n'+d.text)+'&url='+encodeURIComponent(d.url),'_blank','noopener,noreferrer,width=700,height=600')};
document.getElementById('shareEmail').onclick=()=>{const d=window.__shareData;if(d)window.location.href='mailto:?subject='+encodeURIComponent(d.title)+'&body='+encodeURIComponent(d.message)};
document.getElementById('shareCopy').onclick=copyShareText;
setupHeaderSearch();
requestUserLocation();
loadData();

